export function markerIcon(marker) {
  const resource = (marker.iconResource ?? "").replace(/^\{[A-Fa-f0-9]+\}/, "");
  if (
    resource !== "UI/Textures/Icons/icons_mapMarkersUI.imageset" ||
    !names.has(marker.iconName)
  )
    return null;
  return { url: "/icons/reforger/map-" + marker.iconName + ".png" };
}
